# Global dictionary to track retry attempts per chat/message thread for the corrector
# Use a ConfigVar so consumers always see the latest value (set via WebUI/API)
CORRECTOR_RETRIES = config_registry.get_var("CORRECTOR_RETRIES", 2)
register_action_safety_config()

_retry_tracker = {}
_STATIC_INJECTION_CACHE: dict[str, tuple[float, dict[str, Any]]] = {}
_GRILLO_ACTIVITY_MESSAGE_ID_RE = re.compile(r"^grillo_[a-z_]+_(\d+)$")


def _extract_json_local(text: str):
    """Local helper to extract JSON from text using transport_layer's extract_json_from_text.

    Returns:
        Parsed JSON object or None if not found
    """
    from core.transport_layer import extract_json_from_text

    return extract_json_from_text(text, return_metadata=False)


def _extract_grillo_activity_log_id(
    context: Dict[str, Any] | None, message: Any
) -> int | None:
    """Resolve the current Grillo activity id from context or synthetic message id."""
    if isinstance(context, dict):
        for key in ("activity_log_id", "grillo_activity_log_id"):
            value = context.get(key)
            if value is None:
                continue
            try:
                return int(value)
            except (TypeError, ValueError):
                continue

    message_id = getattr(message, "message_id", None)
    if not isinstance(message_id, str):
        return None

    match = _GRILLO_ACTIVITY_MESSAGE_ID_RE.match(message_id.strip())
    if not match:
        return None
    try:
        return int(match.group(1))
    except (TypeError, ValueError):
        return None


def _normalize_diary_emotions(emotions_payload: Any) -> List[Dict[str, Any]]:
    """Normalize emotion payloads into ai_diary's list-of-dicts shape."""
    if isinstance(emotions_payload, list):
        normalized: List[Dict[str, Any]] = []
        for entry in emotions_payload:
            if isinstance(entry, dict) and entry.get("type"):
                normalized.append(entry)
        return normalized

    if not isinstance(emotions_payload, dict):
        return []

    normalized = []
    for emotion_type, intensity in emotions_payload.items():
        normalized.append({"type": str(emotion_type), "intensity": intensity})
    return normalized


def _extract_diary_metadata_from_actions(
    processed_actions: List[Dict[str, Any]],
    context: Dict[str, Any] | None,
) -> Dict[str, Any]:
    """Collect diary metadata explicitly expressed by the LLM across actions/meta."""
    diary_payload: Dict[str, Any] = {}

    for action in processed_actions:
        if action.get("type") == "create_personal_diary_entry":
            payload = action.get("payload") or {}
            if isinstance(payload, dict):
                diary_payload.update(payload)
            break

    if not diary_payload.get("emotions"):
        for action in reversed(processed_actions):
            if action.get("type") != "update_emotion_state":
                continue
            payload = action.get("payload") or {}
            if isinstance(payload, dict):
                emotions_payload = payload.get("emotions", payload)
                diary_payload["emotions"] = _normalize_diary_emotions(emotions_payload)
            break

    llm_response_text = (
        context.get("llm_response_text") if isinstance(context, dict) else None
    )
    if isinstance(llm_response_text, str) and llm_response_text.strip():
        parsed_llm = _extract_json_local(llm_response_text)
        if isinstance(parsed_llm, dict):
            meta = parsed_llm.get("meta") or {}
            rationale = meta.get("rationale") if isinstance(meta, dict) else None
            if (
                isinstance(meta, dict)
                and isinstance(rationale, str)
                and rationale.strip()
            ):
                diary_payload.setdefault("personal_thought", rationale.strip())

    return diary_payload


def _maybe_unescape_text_in_payload(payload: dict) -> None:
    """Detect and unescape common double-escaped sequences in payload['text'].

    Many LLMs or intermediate handlers sometimes produce double-escaped JSON
    strings (e.g. "\\u2728" or "\\n\\n" inside the value). This helper
    safely attempts to decode those sequences into proper unicode / newlines
    so interfaces receive human-readable text.

    The function mutates payload in-place and is intentionally conservative
    (swallows exceptions) to avoid breaking other flows.
    """
    if not isinstance(payload, dict):
        return

    text = payload.get("text")
    if not text or not isinstance(text, str):
        return

    # Recover common mojibake (UTF-8 bytes decoded as latin-1/cp1252)
    try:
        from core.text_utils import try_recover_mojibake

        recovered = try_recover_mojibake(text)
        if recovered and recovered != text:
            payload["text"] = recovered
            text = recovered
    except Exception:
        # Non-fatal — keep original text if recovery fails
        pass

    # Quick heuristic — only attempt to decode when we see backslash escapes
    if (
        "\\n" not in text
        and "\\u" not in text
        and "\\t" not in text
        and "\\r" not in text
        and "\\x" not in text
    ):
        return

    try:
        # unicode_escape converts sequences like \uXXXX, \n, \t into their
        # actual characters. Use a bytes->unicode roundtrip for robustness.
        unescaped = bytes(text, "utf-8").decode("unicode_escape")

        # Only replace when the result is different (avoid accidental transformations)
        if unescaped != text:
            payload["text"] = unescaped
    except Exception:
        # Non-fatal — leave payload untouched on error
        return


async def _maybe_record_grillo_outbound_message(
    action_type: str, payload: dict, context: Dict[str, Any]
) -> None:
    """Best-effort: if a message_* action was produced by a Grillo beat, store its outbound text.

    Grillo beats carry an `activity_log_id` in the context dict (see GrilloPlugin._enqueue_with_low_priority).
    When the LLM decides to send an outbound message (e.g. Telegram), we persist that text to
    `grillo_activity_log.response_text` so History > Grillo shows what was actually said.
    """
    try:
        if (
            not action_type
            or not isinstance(action_type, str)
            or not action_type.startswith("message")
        ):
            return
        if not isinstance(payload, dict):
            return
        if not isinstance(context, dict):
            return

        activity_log_id = context.get("activity_log_id") or context.get(
            "grillo_activity_log_id"
        )
        if not activity_log_id:
            return

        text = payload.get("text")
        if not text or not isinstance(text, str):
            return

        from core.core_initializer import PLUGIN_REGISTRY

        # Use PLUGIN_REGISTRY to avoid importing plugin internals in core
        grillo_plugin = None
        if isinstance(PLUGIN_REGISTRY, dict):
            grillo_plugin = PLUGIN_REGISTRY.get("grillo_plugin") or PLUGIN_REGISTRY.get(
                "grillo_impl"
            )
        else:
            try:
                grillo_plugin = getattr(PLUGIN_REGISTRY, "get", lambda k: None)(
                    "grillo_plugin"
                )
            except Exception:
                grillo_plugin = None

        if grillo_plugin is None:
            return
        setter = getattr(grillo_plugin, "set_activity_response_text", None)
        if not callable(setter):
            return

        await setter(int(activity_log_id), text, append=True)
    except Exception as e:
        # Never fail message sending because of Grillo tracking
        log_debug(f"[action_parser] Failed to record Grillo outbound message: {e}")


async def _grillo_recent_same_message(
    interface_path: str, text: str, window: float
) -> bool:
    """Return True if the synth sent *text* to *interface_path* within *window* seconds.

    This is a light database lookup used by Grillo beats to avoid repeating the
    very same question over and over when the conversation has not progressed.
    """
    if not interface_path or not text:
        return False
    try:
        from core.db import execute_query
        from datetime import datetime, timedelta, timezone

        threshold = datetime.now(timezone.utc) - timedelta(seconds=window)
        rows = await execute_query(
            """
            SELECT COUNT(*)
            FROM chat_history_cache
            WHERE interface_path = %s
              AND COALESCE(sender_id,'') IN (%s,%s)
              AND message_text = %s
              AND timestamp > %s
            """,
            (interface_path, "self", "synth", text, threshold),
        )
        if rows and len(rows) > 0:
            r = rows[0]
            count = int(r[0] if isinstance(r, (list, tuple)) else r.get("cnt", 0))
            return count > 0
    except Exception as e:
        log_debug(f"[action_parser] grillo dedupe lookup failed: {e}")
    return False


