def _get_retry_key(message):
    """Generate a unique key for tracking retries based on interface_path.

    Uses interface_path to uniquely identify conversation context.
    """
    interface_path = getattr(message, "interface_path", None)

    def _norm(value):
        if value is None:
            return "none"
        return str(value)

    return _norm(interface_path)


def _should_retry(message, max_retries: int | None = None) -> bool:
    """Check if we should attempt retry for this message context.

    If max_retries is None we read the dynamic `CORRECTOR_RETRIES` value.
    """
    if max_retries is None:
        max_retries = int(CORRECTOR_RETRIES)
    retry_key = _get_retry_key(message)
    current_time = time.time()

    # Clean up old retry entries (older than 5 minutes)
    cutoff_time = current_time - 300  # 5 minutes
    keys_to_remove = [
        k for k, (count, timestamp) in _retry_tracker.items() if timestamp < cutoff_time
    ]
    for key in keys_to_remove:
        del _retry_tracker[key]

    # Check current retry count
    retry_count, _ = _retry_tracker.get(retry_key, (0, current_time))
    return retry_count < max_retries


def _increment_retry(message):
    """Increment retry count for this message context."""
    retry_key = _get_retry_key(message)
    current_time = time.time()
    retry_count, _ = _retry_tracker.get(retry_key, (0, current_time))
    _retry_tracker[retry_key] = (retry_count + 1, current_time)
    return retry_count + 1


