# Cache for interface actions discovered via the interface registry
_INTERFACE_ACTIONS: Dict[str, str] | None = None


def _load_interface_actions() -> Dict[str, str]:
    """Return a mapping of action_type -> interface_name from registered interfaces."""
    global _INTERFACE_ACTIONS

    if _INTERFACE_ACTIONS is not None:
        log_debug(
            f"[action_parser] 🔄 Returning cached interface actions ({len(_INTERFACE_ACTIONS)})"
        )
        return _INTERFACE_ACTIONS

    try:
        from core.core_initializer import INTERFACE_REGISTRY
    except Exception as e:  # pragma: no cover - registry unavailable
        log_warning(f"[action_parser] Unable to access INTERFACE_REGISTRY: {e}")
        INTERFACE_REGISTRY = {}

    actions: Dict[str, str] = {}
    for name, iface in INTERFACE_REGISTRY.items():
        try:
            if hasattr(iface, "get_supported_actions"):
                supported = iface.get_supported_actions()
                if isinstance(supported, dict):
                    for act in supported.keys():
                        actions[act] = name

            # Dynamic check for supported actions
            if hasattr(iface, "get_supported_action_types"):
                action_types = iface.get_supported_action_types()
                if isinstance(action_types, (list, set)):
                    for act in action_types:
                        actions[act] = name

        except Exception as e:  # pragma: no cover - defensive
            log_debug(f"[action_parser] Error inspecting interface {name}: {e}")

    _INTERFACE_ACTIONS = actions
    return actions


def get_supported_action_types() -> set[str]:
    """Return all supported action types discovered from plugins, interfaces, and validation registry."""
    supported_types: set[str] = set()

    # Add action types from validation registry (new centralized system)
    try:
        validation_registry = get_validation_registry()
        supported_types.update(validation_registry.get_supported_action_types())
    except Exception as e:
        log_warning(
            f"[action_parser] Error getting action types from validation registry: {e}"
        )

    # Legacy discovery from plugins
    try:
        for plugin in _load_action_plugins():
            if hasattr(plugin, "get_supported_action_types"):
                plugin_types = plugin.get_supported_action_types()
                if isinstance(plugin_types, (list, set)):
                    supported_types.update(plugin_types)
            elif hasattr(plugin, "get_supported_actions"):
                plugin_actions = plugin.get_supported_actions()
                if isinstance(plugin_actions, dict):
                    supported_types.update(plugin_actions.keys())
                elif isinstance(plugin_actions, (list, set, tuple)):
                    supported_types.update(plugin_actions)
    except Exception as e:
        log_warning(f"[action_parser] Error discovering action types: {e}")

    # Legacy discovery from interfaces
    try:
        supported_types.update(_load_interface_actions().keys())
    except Exception as e:  # pragma: no cover - defensive
        log_debug(f"[action_parser] Error loading interface actions: {e}")

    # Action metadata published by the core initializer should count as known
    # action types even when the corresponding handler is intentionally absent.
    # This lets safety policy classify them before dispatch.
    supported_types.update(_get_core_declared_action_types())

    return supported_types


def _get_core_declared_action_types() -> set[str]:
    """Return action types declared in core_initializer.actions_block."""

    try:
        from core.core_initializer import core_initializer

        available_actions = (core_initializer.actions_block or {}).get(
            "available_actions", {}
        )
        if isinstance(available_actions, dict):
            return set(available_actions.keys())
    except Exception as e:
        log_debug(f"[action_parser] Error loading core action metadata: {e}")

    return set()


def _get_builtin_interface_message_action_types() -> set[str]:
    """Return canonical built-in interface message action types."""

    return {
        "message_telegram_bot",
        "message_discord_bot",
        "message_synth_webui",
        "message_matrix_chat",
        "message_ollama_serve",
    }


# ID-style fields coerced to *int* only — a chat/user/message id is never a
# float, and a quoted id like ``"5551234567"`` must become an int for DB lookups.
_INT_ID_FIELDS = {"chat_id", "user_id", "message_id"}

# Numeric *parameter* fields (counts, limits, time windows). Coerced to int when
# integral, float otherwise. Grammar-constrained local models routinely quote
# numbers (``"limit": "5"``) — valid JSON, but the string then breaks downstream
# int math and SQL ``LIMIT`` clauses. Normalizing here fixes every such action at
# once rather than per-plugin. Genuinely string-typed numeric fields (e.g. the
# Telegram ``target`` id, free text) are intentionally absent so they stay strings.
_NUMERIC_PARAM_FIELDS = {
    "limit",
    "offset",
    "count",
    "index",
    "page",
    "page_size",
    "depth",
    "top_k",
    "lines",
    "context",
    "context_lines",
    "cycles",
    "max_results",
    "max_memories",
    "total_count",
    "total_pages",
    "older_than_days",
    "older_than_hours",
    "days",
    "hours",
    "minutes",
    "seconds",
    "duration",
    "intensity",
    "threshold",
    "temperature",
}


# Field names small/local models substitute for the required ``text`` field
# on message_* actions (telegram, discord, matrix, reddit, x, ...). Order is
# priority — first match wins if a model somehow emits more than one.
_TEXT_FIELD_ALIASES = ("message_text", "content", "message", "reply", "speech", "body")


def _normalize_text_field_alias(action_type: str, payload: dict) -> None:
    """Rename a misnamed text field to ``text`` in-place for message_* actions.

    Local models frequently emit ``message_text``/``content``/``message`` instead
    of the required ``text`` key. The JSON itself is valid, so this isn't a parse
    error — it's a field-naming mismatch that would otherwise round-trip through
    a full LLM correction call just to rename a key. Fixing it here avoids that
    wasted correction turn.
    """
    if not action_type.startswith("message_"):
        return
    if payload.get("text"):
        return
    for alias in _TEXT_FIELD_ALIASES:
        value = payload.get(alias)
        if isinstance(value, str) and value.strip():
            payload["text"] = payload.pop(alias)
            log_debug(
                f"[action_parser] Normalized {action_type}.payload: "
                f"renamed '{alias}' -> 'text'"
            )
            return


def _normalize_payload(action_type: str, payload: dict) -> None:
    """Normalize a payload in-place so quoted numbers become real numbers.

    Local models behind ``force_action_grammar`` (and small models generally)
    often emit numeric values as JSON strings — ``"limit": "5"`` instead of
    ``"limit": 5``. The shape is valid, but the string then breaks downstream
    integer math and SQL ``LIMIT`` clauses. We coerce two field classes,
    recursively through nested dicts and lists:

    * ID-style fields (``chat_id``, ``user_id``, ``message_id``,
      ``animation_state``, anything ending in ``_id``) → ``int``.
    * Known numeric parameter fields (see ``_NUMERIC_PARAM_FIELDS``) → ``int``
      when integral, ``float`` otherwise.

    Non-numeric strings, already-numeric values, and string-typed fields such as
    the Telegram ``target`` id are left untouched.
    """

    _normalize_text_field_alias(action_type, payload)

    def _coerce_int(value):
        """Convert a clean integer string to ``int``; otherwise return as-is."""
        if isinstance(value, str):
            s = value.strip()
            if s.lstrip("-").isdigit():
                try:
                    return int(s)
                except (ValueError, TypeError):
                    pass
        return value

    def _coerce_number(value):
        """Convert a clean numeric string to ``int`` (integral) or ``float``."""
        if not isinstance(value, str):
            return value
        s = value.strip()
        if s.lstrip("-").isdigit():
            try:
                return int(s)
            except (ValueError, TypeError):
                return value
        # Plain decimal like "0.9" or "-1.5" — reject inf/nan/"1e3" by requiring
        # exactly one dot with digits on both sides.
        if s.count(".") == 1:
            intpart, _, fracpart = s.lstrip("-").partition(".")
            if intpart.isdigit() and fracpart.isdigit():
                try:
                    return float(s)
                except (ValueError, TypeError):
                    return value
        return value

    def _walk(obj, path: str) -> None:
        if isinstance(obj, dict):
            for key, value in list(obj.items()):
                if isinstance(value, (dict, list)):
                    _walk(value, f"{path}.{key}")
                    continue
                if not isinstance(key, str):
                    continue
                if key in _INT_ID_FIELDS or key.endswith("_id"):
                    coerced = _coerce_int(value)
                elif key in _NUMERIC_PARAM_FIELDS:
                    coerced = _coerce_number(value)
                else:
                    continue
                if coerced is not value:
                    obj[key] = coerced
                    log_debug(
                        f"[action_parser] Normalized {action_type}.payload"
                        f"{path}.{key}: {value!r} -> {coerced!r}"
                    )
        elif isinstance(obj, list):
            for i, item in enumerate(obj):
                if isinstance(item, (dict, list)):
                    _walk(item, f"{path}[{i}]")

    _walk(payload, "")


def _attempt_auto_fix(actions: list) -> bool:
    """Apply simple corrections to payloads, returning True if anything changed.

    At the moment the only fix is to re-run ``_normalize_payload`` (which
    converts numeric-string IDs into ints and strips whitespace); this lets us
    recover from trivial type mismatches without pinging the LLM again.  If we
    discover additional common errors we can extend this helper.
    """
    modified = False
    for a in actions:
        payload = a.get("payload")
        if isinstance(payload, dict):
            before = json.dumps(payload, sort_keys=True)
            _normalize_payload(a.get("type", ""), payload)
            after = json.dumps(payload, sort_keys=True)
            if before != after:
                modified = True
    return modified


def _validate_payload(action_type: str, payload: dict, errors: List[str]) -> None:
    """Validate payload using centralized validation registry and legacy plugin/interface validation.

    This function implements the new Dynamic Component Validation System that removes
    hardcoded validation rules from the corrector. Components register their validation
    rules dynamically, and this function applies them automatically.

    See docs/validation_system.rst for complete documentation.
    """
    """Validate payload using centralized validation registry and legacy plugin/interface validation."""

    # First, use the centralized validation registry (new system)
    try:
        validation_registry = get_validation_registry()
        registry_errors = validation_registry.validate_action_payload(
            action_type, payload
        )
        if registry_errors:
            errors.extend(registry_errors)
            log_debug(
                f"[action_parser] Validation registry added {len(registry_errors)} errors for {action_type}"
            )
    except Exception as e:
        log_warning(f"[action_parser] Error using validation registry: {e}")

    # Legacy validation - keep for backward compatibility until all components migrate
    try:
        for plugin in _load_action_plugins():
            supports_action = False
            try:
                if hasattr(plugin, "get_supported_action_types"):
                    if action_type in plugin.get_supported_action_types():
                        supports_action = True
                elif hasattr(plugin, "get_supported_actions"):
                    actions = plugin.get_supported_actions()
                    if isinstance(actions, dict) and action_type in actions:
                        supports_action = True
                    elif (
                        isinstance(actions, (list, set, tuple))
                        and action_type in actions
                    ):
                        supports_action = True
            except Exception as e:
                log_debug(
                    f"[action_parser] Error checking plugin support for {action_type}: {e}"
                )
                continue

            if supports_action:
                if hasattr(plugin, "validate_payload"):
                    try:
                        plugin_errors = plugin.validate_payload(action_type, payload)
                        if plugin_errors and isinstance(plugin_errors, list):
                            errors.extend(plugin_errors)
                            log_debug(
                                f"[action_parser] Plugin {plugin.__class__.__name__} added {len(plugin_errors)} validation errors"
                            )
                    except Exception as e:
                        log_warning(
                            f"[action_parser] Error validating payload with plugin {plugin.__class__.__name__}: {e}"
                        )
                elif hasattr(plugin, "validate_action"):
                    try:
                        action_dict = {"type": action_type, "payload": payload}
                        plugin_errors = plugin.validate_action(action_dict)
                        if plugin_errors and isinstance(plugin_errors, list):
                            errors.extend(plugin_errors)
                            log_debug(
                                f"[action_parser] Plugin {plugin.__class__.__name__} added {len(plugin_errors)} validation errors"
                            )
                    except Exception as e:
                        log_warning(
                            f"[action_parser] Error validating action with plugin {plugin.__class__.__name__}: {e}"
                        )
                else:
                    # Plugin doesn't have validation - that's OK, skip
                    log_debug(
                        f"[action_parser] Plugin {plugin.__class__.__name__} supports {action_type} but has no validation method"
                    )

        # Interface-based validation
        iface_name = _load_interface_actions().get(action_type)
        if iface_name:
            try:
                from core.core_initializer import INTERFACE_REGISTRY

                iface = INTERFACE_REGISTRY.get(iface_name)
                if iface and hasattr(iface, "validate_payload"):
                    iface_errors = iface.validate_payload(action_type, payload)
                    if iface_errors and isinstance(iface_errors, list):
                        errors.extend(iface_errors)
                        log_debug(
                            f"[action_parser] Interface {iface_name} added {len(iface_errors)} validation errors"
                        )
            except Exception as e:  # pragma: no cover - defensive
                log_warning(
                    f"[action_parser] Error validating payload with interface {iface_name}: {e}"
                )
    except Exception as e:
        log_error(f"[action_parser] Error during payload validation: {e}")


def validate_action(
    action: dict, context: dict | None = None, original_message=None
) -> Tuple[bool, List[str]]:
    """Validate an action dictionary.

    Parameters
    ----------
    action : dict
        Dictionary describing an action.
    context : dict, optional
        Context information for interface inference.
    original_message : optional
        Original message for interface inference.

    Returns
    -------
    tuple[bool, list[str]]
        A tuple containing a boolean validity flag and a list of error messages.
    """

    errors: List[str] = []

    # Ignore optional description fields from the LLM
    if isinstance(action, dict) and "description" in action:
        action = {k: v for k, v in action.items() if k != "description"}

    if not isinstance(action, dict):
        return False, ["action must be a dict"]

    # Validate action type - with specific action names, interface is implicit
    supported_types = set(get_supported_action_types())
    supported_types.update(_get_core_declared_action_types())
    supported_types.update(_get_builtin_interface_message_action_types())
    action_type = action.get("type")
    if (
        action_type
        and isinstance(action_type, str)
        and action_type.startswith("default_api:")
    ):
        action_type = action_type.split("default_api:", 1)[1]
        action["type"] = action_type

    if not action_type:
        errors.append("Missing 'type'")
    elif action_type not in supported_types:
        # No supported component found for this action type. Do not perform
        # hardcoded conversions here — resolution of legacy or alias names
        # should be handled by the ValidationRegistry or a dedicated adapter.
        errors.append(
            f"Unsupported type '{action_type}' - no plugin or interface found to handle it"
        )

    payload = action.get("payload")

    # Some actions (like bio plugins) support both payload and direct field format
    # for backward compatibility
    actions_with_flexible_payload = ["bio_update", "bio_full_request"]

    if payload is None and action_type not in actions_with_flexible_payload:
        errors.append("Missing 'payload'")
    elif payload is not None and not isinstance(payload, dict):
        errors.append("'payload' must be a dict")

    # If action type is not supported, allow validation registry to attempt
    # resolving legacy/alias names (e.g., 'message_send'). This keeps the
    # resolution logic centralized and configurable.
    if action_type and action_type not in supported_types:
        try:
            validation_registry = get_validation_registry()
            resolved = validation_registry.resolve_action_alias(
                action_type, payload or {}
            )
            if resolved:
                log_debug(
                    f"[action_parser] Resolved alias '{action_type}' -> '{resolved}' via ValidationRegistry"
                )
                action_type = resolved
                action["type"] = resolved
                # fall through to normal validation below
        except Exception as e:
            log_warning(
                f"[action_parser] Alias resolution failed for '{action_type}': {e}"
            )

    # Dynamic validation - delegate to plugins or interfaces that support this action type
    if (
        action_type
        and (isinstance(payload, dict) or action_type in actions_with_flexible_payload)
        and action_type in supported_types
    ):
        # Normalize payload before validation (convert string numbers to int)
        if payload:
            _normalize_payload(action_type, payload)
        _validate_payload(action_type, payload or {}, errors)

        if _is_restricted_action(action_type):
            mode = str(RESTRICT_ACTIONS).lower()
            if mode in ("on", "deny_all"):
                errors.append(f"Action '{action_type}' is restricted")
            elif mode == "trainer_only":
                # Check if user is trainer using abstract context
                try:
                    from core.abstract_context import AbstractContext, AbstractUser

                    interface_name = "unknown"
                    if context:
                        interface_name = context.get("interface_name", "unknown")
                    user_id = getattr(
                        getattr(original_message, "from_user", None), "id", None
                    )

                    if user_id is not None:
                        abstract_user = AbstractUser(
                            id=user_id, interface_name=interface_name
                        )
                        abstract_context = AbstractContext(
                            interface_name, user=abstract_user
                        )

                        if not abstract_context.is_trainer():
                            errors.append(
                                f"Action '{action_type}' is restricted to trainer"
                            )
                except Exception as e:
                    log_warning(f"Could not verify trainer status: {e}")
                    errors.append(
                        f"Action '{action_type}' requires trainer verification"
                    )

    return len(errors) == 0, errors


# Cache for discovered action plugins
_ACTION_PLUGINS: List[Any] | None = None


def _load_action_plugins() -> List[Any]:
    """Return plugin instances registered with the core initializer."""
    global _ACTION_PLUGINS
    if _ACTION_PLUGINS is not None:
        log_debug(
            f"[action_parser] 🔄 Returning cached plugins ({len(_ACTION_PLUGINS)})"
        )
        return _ACTION_PLUGINS

    try:
        from core.core_initializer import PLUGIN_REGISTRY
    except Exception as e:
        log_warning(f"[action_parser] Unable to access PLUGIN_REGISTRY: {e}")
        PLUGIN_REGISTRY = {}

    _ACTION_PLUGINS = list(PLUGIN_REGISTRY.values())
    log_info(
        f"[action_parser] 🔍 Loaded {len(_ACTION_PLUGINS)} plugin(s) from registry"
    )
    return _ACTION_PLUGINS


def _plugins_for(action_type: str) -> List[Any]:
    plugins = []
    loaded_plugins = _load_action_plugins()
    log_info(
        f"[action_parser] _plugins_for({action_type}): Searching in {len(loaded_plugins)} loaded plugins"
    )

    for plugin in loaded_plugins:
        try:
            if hasattr(plugin, "get_supported_action_types"):
                action_types = plugin.get_supported_action_types()
                log_debug(
                    f"[action_parser] Plugin {plugin.__class__.__name__}.get_supported_action_types(): {action_types}"
                )
                if action_types and action_type in action_types:
                    plugins.append(plugin)
                    log_debug(
                        f"[action_parser] ✅ Plugin {plugin.__class__.__name__} supports {action_type} (via action_types)"
                    )
                    # Optimization: Stop searching for user-facing message actions after first match
                    try:
                        if _is_interface_message_action(action_type):
                            log_debug(
                                f"[action_parser] ⚡ Optimization: Stopping search for user-facing action {action_type} after first match"
                            )
                            break
                    except Exception:
                        pass
                    continue

            if hasattr(plugin, "get_supported_actions"):
                actions_dict = plugin.get_supported_actions()
                log_debug(
                    f"[action_parser] Plugin {plugin.__class__.__name__}.get_supported_actions(): {actions_dict}"
                )
                if isinstance(actions_dict, dict) and action_type in actions_dict:
                    plugins.append(plugin)
                    log_debug(
                        f"[action_parser] ✅ Plugin {plugin.__class__.__name__} supports {action_type} (via actions_dict)"
                    )
                    # Optimization: Stop searching for user-facing message actions after first match
                    try:
                        if _is_interface_message_action(action_type):
                            log_debug(
                                f"[action_parser] ⚡ Optimization: Stopping search for user-facing action {action_type} after first match"
                            )
                            break
                    except Exception:
                        pass
                    continue

        except Exception as e:
            log_error(f"[action_parser] Error querying plugin {plugin}: {repr(e)}")

    # Special handling for tts_speak: explicitly check for master TTS plugin if not found
    if action_type == "tts_speak" and not plugins:
        for plugin in loaded_plugins:
            if plugin.__class__.__name__ in {"TTSMasterPlugin", "TTSPlugin"}:
                plugins.append(plugin)
                log_info(
                    "[action_parser] ✅ Explicitly added TTS master plugin for tts_speak"
                )
                break

    # Special handling for trigger_weather_report: explicitly check for WeatherPlugin if not found
    if action_type == "trigger_weather_report" and not plugins:
        for plugin in loaded_plugins:
            if plugin.__class__.__name__ == "WeatherPlugin":
                plugins.append(plugin)
                log_info(
                    "[action_parser] ✅ Explicitly added WeatherPlugin for trigger_weather_report"
                )
                break

    try:
        from core.core_initializer import INTERFACE_REGISTRY
    except Exception as e:  # pragma: no cover - defensive
        log_error(f"[action_parser] Error loading INTERFACE_REGISTRY: {e}")
        INTERFACE_REGISTRY = {}

    for name, iface in INTERFACE_REGISTRY.items():
        try:
            if hasattr(iface, "get_supported_action_types"):
                action_types = iface.get_supported_action_types()
                log_debug(
                    f"[action_parser] Interface {name}.get_supported_action_types(): {action_types}"
                )
                if action_types and action_type in action_types:
                    plugins.append(iface)
                    log_debug(
                        f"[action_parser] ✅ Interface {name} supports {action_type} (via action_types)"
                    )
                    # Optimization: Stop searching for user-facing message actions after first match
                    try:
                        if _is_interface_message_action(action_type):
                            log_debug(
                                f"[action_parser] ⚡ Optimization: Stopping search for user-facing action {action_type} after first match"
                            )
                            break
                    except Exception:
                        pass
                    continue

            if hasattr(iface, "get_supported_actions"):
                actions_dict = iface.get_supported_actions()
                log_debug(
                    f"[action_parser] Interface {name}.get_supported_actions(): {actions_dict}"
                )
                if isinstance(actions_dict, dict) and action_type in actions_dict:
                    plugins.append(iface)
                    log_debug(
                        f"[action_parser] ✅ Interface {name} supports {action_type} (via actions_dict)"
                    )
                    # Optimization: Stop searching for user-facing message actions after first match
                    try:
                        if _is_interface_message_action(action_type):
                            log_debug(
                                f"[action_parser] ⚡ Optimization: Stopping search for user-facing action {action_type} after first match"
                            )
                            break
                    except Exception:
                        pass
                    continue

            log_debug(
                f"[action_parser] ❌ Interface {name} does not support {action_type}"
            )
        except Exception as e:
            log_error(f"[action_parser] Error querying interface {name}: {repr(e)}")

    log_info(
        f"[action_parser] _plugins_for({action_type}): Found {len(plugins)} supporting plugins: {[p.__class__.__name__ for p in plugins]}"
    )
    return plugins


def set_available_plugins(interfaces, cortex_engine, plugins):
    """Set available plugins and their details for the action parser."""
    global ACTIVE_INTERFACES, ACTIVE_CORTEX_ENGINE, AVAILABLE_PLUGINS

    # Set active interfaces
    ACTIVE_INTERFACES = set(interfaces)
    log_info("[action_parser] Active interfaces set.")

    # Set active Cortex engine
    ACTIVE_CORTEX_ENGINE = cortex_engine
    log_info(f"[action_parser] Active Cortex engine: {ACTIVE_CORTEX_ENGINE}")

    # Set available plugins
    AVAILABLE_PLUGINS = plugins
    log_info("[action_parser] Available plugins set.")


def _is_interface_message_action(action_type: str) -> bool:
    """Return True if the given action_type is a registered interface action that
    represents a user-facing message (i.e., capable of sending textual messages).

    This function inspects the registered interfaces, preferring the interface's
    explicit metadata rather than hard-coded name checks.
    """
    try:
        # Map action to interface name
        iface_name = _load_interface_actions().get(action_type)
        if not iface_name:
            return False

        from core.core_initializer import INTERFACE_REGISTRY

        iface = INTERFACE_REGISTRY.get(iface_name)
        if not iface:
            return False

        # If the interface exposes a send_message method, it's likely a user-facing
        # messaging interface; verify that the action belongs to the interface's
        # supported actions to avoid false positives.
        if hasattr(iface, "send_message"):
            # Check that the action_type is indeed listed by the interface
            if hasattr(iface, "get_supported_actions"):
                supported = iface.get_supported_actions() or {}
                if action_type in supported:
                    return True
            if hasattr(iface, "get_supported_action_types"):
                action_types = iface.get_supported_action_types() or []
                if action_type in action_types:
                    return True

        # Fallback: examine the action metadata for a 'text' required/optional field
        if hasattr(iface, "get_supported_actions"):
            supported = iface.get_supported_actions() or {}
            meta = supported.get(action_type, {})
            if isinstance(meta, dict):
                req = meta.get("required_fields") or meta.get("required_params") or []
                opt = meta.get("optional_fields") or meta.get("optional_params") or []
                if isinstance(req, (list, set)) and "text" in req:
                    return True
                if isinstance(opt, (list, set)) and "text" in opt:
                    return True

    except Exception:
        return False

    return False


# Variables to store the state
ACTIVE_INTERFACES = set()
ACTIVE_CORTEX_ENGINE = None
AVAILABLE_PLUGINS = []


async def _handle_plugin_action(
    action: Dict[str, Any], context: Dict[str, Any], bot, original_message
):
    action_type = action.get("type")
    if not action_type:
        log_warning("[action_parser] Action is missing a 'type'")
        return {"error": "Action is missing a 'type'"}
    iface_target = action.get("interface")

    log_info(
        f"[action_parser] 🎯 Handling action: type={action_type}, interface={iface_target}"
    )

    plugins = _plugins_for(action_type)
    log_info(
        f"[action_parser] 🔍 Found {len(plugins)} plugins for action type '{action_type}'"
    )

    if not plugins:
        log_info(
            f"[action_parser] 📭 No plugin found for action type '{action_type}', attempting interface dispatch"
        )

        # Determine target interface from action or registry mapping
        iface_name = iface_target or _load_interface_actions().get(action_type)

        # If interface not found, try to refresh the interface actions cache
        if not iface_name:
            try:
                if _is_interface_message_action(action_type):
                    global _INTERFACE_ACTIONS
                    _INTERFACE_ACTIONS = None  # Force refresh
                    iface_name = _load_interface_actions().get(action_type)
            except Exception:
                pass

        try:
            from core.core_initializer import INTERFACE_REGISTRY

            interface = INTERFACE_REGISTRY.get(iface_name) if iface_name else None
            if (
                interface
                and action_type.startswith("message")
                and hasattr(interface, "send_message")
            ):
                payload = action.get("payload", {})
                # Normalize text payloads to recover double-escaped sequences
                try:
                    _maybe_unescape_text_in_payload(payload)
                except Exception:
                    log_debug(
                        "[action_parser] Text unescape normalization failed (non-fatal)"
                    )
                # Strip emotion / meta tags from outbound text so they
                # never leak to the end-user interface.
                if isinstance(payload, dict):
                    _raw_text = payload.get("text")
                    if isinstance(_raw_text, str) and "{" in _raw_text:
                        try:
                            from plugins.emotion_manager import (
                                strip_emotion_tags,
                            )

                            _cleaned = strip_emotion_tags(_raw_text)
                            if _cleaned != _raw_text:
                                payload["text"] = _cleaned
                                log_debug(
                                    "[action_parser] Stripped emotion/meta tags from action payload text"
                                )
                        except Exception:
                            pass
                log_info(
                    f"[action_parser] ✉️ Dispatching message action to interface '{iface_name}'"
                )
                try:
                    result = interface.send_message(
                        payload, original_message=original_message
                    )
                    if inspect.iscoroutine(result):
                        await result
                    return None
                except Exception as e:
                    log_error(
                        f"[action_parser] ❌ Error executing {action_type} via interface {iface_name}: {repr(e)}"
                    )
                return
        except Exception as e:  # pragma: no cover - defensive
            log_warning(f"[action_parser] Interface dispatch failed: {e}")

        if action_type == "trigger_weather_report":
            log_warning(
                "[action_parser] ⚠️ Suppressing failed 'trigger_weather_report' to prevent recursion loop."
            )
            return None

        log_error(
            f"[action_parser] ❌ No plugin or interface supports action type '{action_type}'"
        )
        return

    for plugin in plugins:
        plugin_iface = getattr(
            plugin.__class__,
            "get_interface_id",
            lambda: plugin.__class__.__name__.lower(),
        )()

        log_info(
            f"[action_parser] 🔌 Checking plugin: {plugin.__class__.__name__} (plugin_interface: {plugin_iface})"
        )

        if iface_target and plugin_iface != iface_target:
            log_info(
                f"[action_parser] ⏭️ Skipping plugin {plugin_iface} (target: {iface_target})"
            )
            continue

        # If this plugin is an interface and exposes send_message, allow it to
        # handle message_* actions (interfaces use send_message rather than
        # execute_action). This ensures message actions are dispatched to
        # interfaces properly.
        if hasattr(plugin, "send_message") and action_type.startswith("message"):
            try:
                payload = action.get("payload", {})
                # Normalize text payload content produced by LLMs (double-escaped unicode/newlines)
                try:
                    _maybe_unescape_text_in_payload(payload)
                except Exception:
                    log_debug(
                        "[action_parser] Text unescape normalization failed for plugin send_message (non-fatal)"
                    )
                # === facial expression tag handling ===
                try:
                    from core.facial_expression_parser import parse_facial_expressions
                    from plugins.facial_expression_plugin import FacialExpressionPlugin
                    from core.animation_handler import get_karada_state_server

                    original_text = payload.get("text", "") or ""
                    clean_text, events = parse_facial_expressions(original_text)
                    if clean_text != original_text:
                        payload["text"] = clean_text
                    if events and get_karada_state_server().has_connected_clients():
                        # find our plugin instance (if loaded)
                        expr_plugin = None
                        from core.core_initializer import PLUGIN_REGISTRY

                        if isinstance(PLUGIN_REGISTRY, dict):
                            for p in PLUGIN_REGISTRY.values():
                                if isinstance(p, FacialExpressionPlugin):
                                    expr_plugin = p
                                    break
                        if expr_plugin:
                            total_chars = len(clean_text)
                            # read settings via persona manager as plugin does
                            from core.persona_manager import get_persona_manager

                            persona_json = None
                            pm = get_persona_manager()
                            current_persona = (
                                getattr(pm, "_current_persona", None) if pm else None
                            )
                            if pm and current_persona is not None:
                                try:
                                    persona_json = pm._load_persona_json(
                                        current_persona.name
                                    )
                                except Exception:
                                    persona_json = None
                            chars_per_sec = (
                                persona_json.get("facial_expression_chars_per_sec", 12)
                                if persona_json
                                else 12
                            )
                            expr_section = (
                                persona_json.get("facial_expressions", {})
                                if persona_json
                                else {}
                            )
                            asyncio.create_task(
                                expr_plugin._play_expression_timeline(
                                    events,
                                    total_chars,
                                    getattr(original_message, "session_id", ""),
                                    chars_per_sec,
                                    expr_section=expr_section,
                                )
                            )
                except Exception:
                    pass

                # If this outbound message originates from a Grillo beat, store it in grillo_activity_log
                try:
                    await _maybe_record_grillo_outbound_message(
                        action_type, payload, context
                    )
                except Exception:
                    pass

                # === send_as_voice: deliver this reply as a spoken voice note ===
                # When the model sets send_as_voice=true on a message_* action,
                # route the text through Vox (TTS). Vox synthesises the audio and
                # dispatches BOTH the audio and the caption text to the interface,
                # so we must NOT also call send_message here (that would duplicate
                # the text). If Vox is disabled or fails, Vox.speak() falls back to
                # sending the text itself, so a plain reply is still delivered.
                if bool(payload.get("send_as_voice")):
                    try:
                        from core.core_initializer import PLUGIN_REGISTRY
                        from plugins.vox_plugin import VoxPlugin

                        vox_plugin = None
                        if isinstance(PLUGIN_REGISTRY, dict):
                            for p in PLUGIN_REGISTRY.values():
                                if isinstance(p, VoxPlugin):
                                    vox_plugin = p
                                    break

                        if vox_plugin is not None:
                            voice_ip = payload.get("interface_path") or getattr(
                                original_message, "interface_path", None
                            )
                            log_info(
                                f"[action_parser] 🎙️ send_as_voice=true — routing '{action_type}' "
                                f"to Vox for interface '{plugin_iface}'"
                            )
                            await vox_plugin.speak(
                                text=payload.get("text", "") or "",
                                interface_path=voice_ip,
                                context=context,
                                original_message=original_message,
                            )
                            return None
                        log_warning(
                            "[action_parser] send_as_voice=true but no Vox plugin "
                            "loaded — falling back to plain text send."
                        )
                    except Exception as e:
                        log_error(
                            f"[action_parser] send_as_voice routing failed: {repr(e)} "
                            "— falling back to plain text send."
                        )

                log_info(
                    f"[action_parser] ✉️ Dispatching message action to interface '{plugin_iface}' via send_message"
                )
                result = plugin.send_message(payload, original_message=original_message)
                if inspect.iscoroutine(result):
                    await result
                log_info(
                    f"[action_parser] ✅ Successfully executed message action via {plugin_iface}"
                )
                return None
            except Exception as e:
                log_error(
                    f"[action_parser] ❌ Error executing {action_type} via interface {plugin_iface}: {repr(e)}"
                )
                continue

        if hasattr(plugin, "execute_action"):
            try:
                payload = action.get("payload", {})
                if not isinstance(payload, dict):
                    payload = vars(payload)
                # Normalize payload.text for execute_action consumers too
                try:
                    _maybe_unescape_text_in_payload(payload)
                except Exception:
                    log_debug(
                        "[action_parser] Text unescape normalization failed for plugin execute_action (non-fatal)"
                    )

                # If this outbound message originates from a Grillo beat, store it in grillo_activity_log
                try:
                    await _maybe_record_grillo_outbound_message(
                        action_type, payload, context
                    )
                except Exception:
                    pass
                new_action = {**action, "payload": payload}
                log_info(
                    f"[action_parser] 🚀 Delegating action to {plugin.__class__.__name__}: type={action_type} interface={plugin_iface}"
                )
                log_debug(
                    "[action_parser] 📦 Action payload: "
                    + json_dumps(redact_multimodal_for_logging(payload))
                )

                result = plugin.execute_action(
                    new_action, context, bot, original_message
                )
                if inspect.iscoroutine(result):
                    result = await result
                # If a plugin explicitly skips this action, fall through to the next handler.
                # "skipped" means "I'm not handling this — try the next plugin".
                if isinstance(result, dict) and result.get("status") == "skipped":
                    log_info(
                        f"[action_parser] ⏭️ Plugin {plugin.__class__.__name__} skipped "
                        f"action '{action_type}' (reason: {result.get('reason', 'unknown')}); "
                        "trying next plugin"
                    )
                    continue
                log_info(
                    f"[action_parser] ✅ Successfully executed action via {plugin_iface}"
                )
                return result
            except Exception as e:
                log_error(
                    f"[action_parser] ❌ Error executing {action_type} with {plugin.__class__.__name__}: {repr(e)}"
                )
                import traceback

                log_error(
                    f"[action_parser] 📄 Full traceback: {traceback.format_exc()}"
                )
        else:
            log_warning(
                f"[action_parser] ⚠️ Plugin {plugin.__class__.__name__} has no execute_action() method"
            )

    # No matching plugin found - collect error for auto-correction
    available_interfaces = (
        list(ACTIVE_INTERFACES) if ACTIVE_INTERFACES else ["No interfaces registered"]
    )
    error_msg = f"Interface '{iface_target}' not found for action '{action_type}'. Available interfaces: {', '.join(available_interfaces)}"

    log_error(
        f"[action_parser] 💥 No plugin matched interface '{iface_target}' for action '{action_type}'"
    )
    return {
        "error": error_msg,
        "action": action,
        "available_interfaces": available_interfaces,
    }


async def run_action(action: Any, context: Dict[str, Any], bot, original_message):
    """Validate and execute a single action or list of actions."""
    log_info(f"[action_parser] 🎬 run_action called with action: {action}")

    if isinstance(action, list):
        log_info(f"[action_parser] 📋 Processing action list with {len(action)} items")
        return await run_actions(action, context, bot, original_message)

    action_type = action.get("type")
    log_info(f"[action_parser] 🔍 Action type detected: {action_type}")

    valid, errors = validate_action(action, context, original_message)
    if not valid:
        error_msg = f"Invalid action: {errors}"
        log_error(f"[action_parser] ❌ {error_msg}")
        return {"error": error_msg}

    action_interface = action.get("interface")

    log_info(
        f"[action_parser] 🚀 Executing action: type={action_type}, interface={action_interface}"
    )

    # Use plugin system for all action types (including messages)
    result = await _handle_plugin_action(action, context, bot, original_message)
    return result


async def _request_selective_correction(
    failed_actions, successful_actions, bot, context, original_message
):
    """Request LLM to fix only the failed actions, while preserving successful ones."""

    fixable_failed_actions = [
        failed for failed in failed_actions if not failed.get("unfixable")
    ]
    unfixable_failed_count = len(failed_actions) - len(fixable_failed_actions)
    if not fixable_failed_actions:
        log_info(
            "[action_parser] Skipping selective correction because all failed actions are unfixable"
        )
        return

    # Build clear correction prompt
    successful_count = len(successful_actions)
    failed_count = len(fixable_failed_actions)

    # Extract successful action types for context
    successful_types = [action.get("type", "unknown") for action in successful_actions]

    # Load plugin and interface schemas for detailed descriptions
    action_schemas = {}

    # Get schemas from plugins
    try:
        for plugin in _load_action_plugins():
            if hasattr(plugin, "get_supported_actions"):
                actions = plugin.get_supported_actions()
                for action_type, action_info in actions.items():
                    action_schemas[action_type] = action_info
            if hasattr(plugin, "get_prompt_instructions"):
                # Store verbose descriptions
                for action_type in (plugin.get_supported_actions() or {}).keys():
                    if hasattr(plugin, "get_prompt_instructions"):
                        instructions = plugin.get_prompt_instructions(action_type)
                        if instructions and action_type in action_schemas:
                            action_schemas[action_type]["_verbose_instructions"] = (
                                instructions
                            )
    except Exception as e:
        log_warning(f"[action_parser] Error loading plugin schemas: {e}")

    # Get schemas from interfaces
    try:
        for iface_name, interface in INTERFACE_REGISTRY.items():
            if hasattr(interface, "get_supported_actions"):
                actions = interface.get_supported_actions()
                for action_type, action_info in actions.items():
                    action_schemas[action_type] = action_info
            # Also pull verbose prompt instructions from interfaces when available
            if hasattr(interface, "get_prompt_instructions"):
                for action_type in (interface.get_supported_actions() or {}).keys():
                    try:
                        instr = interface.get_prompt_instructions(action_type)
                        if instr and action_type in action_schemas:
                            action_schemas[action_type]["_verbose_instructions"] = instr
                    except Exception:
                        pass
    except Exception as e:
        log_warning(f"[action_parser] Error loading interface schemas: {e}")

    # Build detailed error descriptions with schemas
    error_details = []
    # we'll also note globally whether any unknown action types occurred
    unknown_actions: list[str] = []
    for failed in fixable_failed_actions:
        action = failed["action"]
        errors = failed["errors"]
        action_type = action.get("type", "unknown")
        schema = action_schemas.get(action_type, {})

        # mark unknown actions for later hinting
        if action_type not in action_schemas:
            unknown_actions.append(action_type)

        detail = {
            "action_type": action_type,
            "errors": errors,
            "original_action": action,
            "description": schema.get("description", "Unknown action"),
            "required_fields": schema.get("required_fields", []),
            "optional_fields": schema.get("optional_fields", []),
        }

        # Add verbose instructions if available (from plugin or interface)
        if "_verbose_instructions" in schema:
            detail["verbose_instructions"] = schema["_verbose_instructions"]

        error_details.append(detail)

    # Create a specialized correction prompt that only asks for failed actions
    instruction = f"""
Your previous response was partially successful:
✅ {successful_count} actions executed successfully: {", ".join(successful_types) if successful_types else "none"}
❌ {failed_count} actions failed and need correction

Please provide ONLY the corrected versions of the failed actions. Do not repeat the {successful_count} successful actions.

FAILED ACTIONS REQUIRING CORRECTION:
"""

    for i, detail in enumerate(error_details, 1):
        instruction += f"\n{i}. ACTION: '{detail['action_type']}'\n"
        instruction += f"   DESCRIPTION: {detail['description']}\n"

        # Add schema information
        if detail["required_fields"]:
            instruction += (
                f"   REQUIRED FIELDS: {', '.join(detail['required_fields'])}\n"
            )
        if detail["optional_fields"]:
            instruction += (
                f"   OPTIONAL FIELDS: {', '.join(detail['optional_fields'])}\n"
            )

        # If this action was unknown, include a generic advisory instead of
        # spitting out the entire current list (which may change depending on
        # loaded plugins).  The corrector will already know which actions are
        # valid; this note is just to highlight the mismatch.
        if (
            detail["description"] == "Unknown action"
            or detail["action_type"] in unknown_actions
        ):
            instruction += (
                f"   NOTE: '{detail['action_type']}' is not a valid action type.\n"
            )

        # Add verbose instructions if available (include description, payload schema, examples, and important notes)
        if "verbose_instructions" in detail:
            vi = detail["verbose_instructions"]
            if vi.get("description"):
                instruction += f"   FULL DESCRIPTION: {vi.get('description')}\n"
            if vi.get("payload"):
                instruction += "   PAYLOAD FIELDS:\n"
                for k, v in vi.get("payload", {}).items():
                    desc = v.get("description", "") if isinstance(v, dict) else str(v)
                    ex = v.get("example", "") if isinstance(v, dict) else ""
                    instruction += f"      - {k}: {desc} (example: {ex})\n"
            if vi.get("examples"):
                instruction += f"   EXAMPLES: {vi.get('examples')}\n"
            if vi.get("important_notes"):
                instruction += "   IMPORTANT NOTES:\n"
                for note in vi.get("important_notes"):
                    instruction += f"      - {note}\n"

        # Add specific errors
        instruction += "   ERRORS FOUND:\n"
        for error in detail["errors"]:
            instruction += f"      ❌ {error}\n"

    instruction += f"""
Respond with JSON containing only the corrected actions (not the successful ones):
{{
  "actions": [
    // Only the fixed versions of failed actions here
  ]
}}

IMPORTANT: Do not include the {successful_count} actions that were already executed successfully ({", ".join(successful_types) if successful_types else "none"}).
"""

    if unfixable_failed_count:
        instruction += "\nDo not retry actions that were blocked by safety policy or otherwise marked unfixable."

    correction_context = {
        "previous_response_status": "partial_success",
        "successful_actions": successful_actions,
        "successful_types": successful_types,
        "successful_count": successful_count,
        "failed_actions": fixable_failed_actions,
        "failed_count": failed_count,
        "unfixable_failed_count": unfixable_failed_count,
        "correction_needed": True,
        "instruction": instruction,
    }

    log_info(
        f"[action_parser] Requesting selective correction for {failed_count} failed actions (preserving {successful_count} successful ones)"
    )
    log_debug(f"[action_parser] Correction context: {correction_context}")

    try:
        # Create a synthetic message with correction context
        import types

        correction_message = types.SimpleNamespace()
        correction_message.chat_id = getattr(original_message, "chat_id", None)
        correction_message.from_cortex = True
        correction_message.original_text = correction_context["instruction"]
        correction_message.text = correction_context["instruction"]

        # Ensure the original message carries correction_context for the transport-layer corrector
        try:
            if hasattr(original_message, "__dict__"):
                original_message.correction_context = correction_context
        except Exception:
            pass

        # Use existing corrector middleware but include original_message in context so
        # run_corrector_middleware can detect selective correction context correctly
        corrected_context = {
            **(context or {}),
            "selective_correction": True,
            "correction_context": correction_context,
            "message": original_message,
        }

        await run_corrector_middleware(
            text=str(correction_context["instruction"]),
            bot=bot,
            context=corrected_context,
            chat_id=getattr(original_message, "chat_id", None),
            thread_id=getattr(original_message, "thread_id", None),
        )
    except Exception as e:
        log_error(f"[action_parser] Failed to request selective correction: {e}")


async def run_actions(actions: Any, context: Dict[str, Any], bot, original_message):
    """Execute multiple actions in sequence.

    If ``actions`` is a single dict, it will be wrapped in a list.
    Valid actions are executed, invalid actions are collected for selective correction.

    Returns:
        dict: {"processed": [successful_actions], "errors": [error_messages], "failed_actions": [failed_actions]}
    """
    if actions is None:
        return {"processed": [], "errors": [], "failed_actions": []}

    if isinstance(actions, dict):
        actions = [actions]
    elif not isinstance(actions, list):
        error_msg = "[action_parser] run_actions expects a list or dict"
        log_error(error_msg)
        return {"processed": [], "errors": [error_msg], "failed_actions": []}

    log_debug(f"[action_parser] run_actions called with {len(actions)} actions")
    log_debug(f"[action_parser] Actions: {actions}")

    processed_actions = []
    collected_errors = []
    failed_actions = []
    action_outputs: List[Dict[str, Any]] = []
    terminal_seen = False

    for idx, action in enumerate(actions):
        try:
            action_type = action.get("type")

            # Halt processing of subsequent non-terminal actions until the LLM
            # has seen the outputs from executed terminal commands.
            if terminal_seen and action_type != "terminal":
                log_info(
                    "[action_parser] ⏸️ Waiting for LLM response before executing remaining actions"
                )
                break

            valid, errors = validate_action(action, context, original_message)
            if not valid:
                error_msg = f"Invalid action {idx}: {errors}"
                log_warning(f"[action_parser] Skipping {error_msg}")
                collected_errors.append(error_msg)
                failed_actions.append(
                    {"index": idx, "action": action, "errors": errors}
                )
                continue

            # --- Safety & autonomy checks for AI/cortex-originated actions ---
            is_from_cortex = (
                hasattr(original_message, "from_cortex")
                and getattr(original_message, "from_cortex")
            ) or context.get("from_cortex", False)

            # Grillo-specific dedupe: if this run originated from a Grillo beat and
            # the message text has already been sent to the same interface_path
            # within the self-window, discard the action early.  This guard works
            # even if the snippet collector failed to filter the chat.
            if is_from_cortex and context.get("grillo_beat"):
                try:
                    action_type = action.get("type") or ""
                    if action_type.startswith("message"):
                        payload = action.get("payload") or {}
                        text = payload.get("text")
                        interface_path = payload.get("interface_path") or context.get(
                            "interface_path"
                        )
                        # use same window as snippet skip for consistency
                        window = float(
                            config_registry.get_value(
                                "GRILLO_OBSERVER_SELF_WINDOW",
                                43200,
                                group="grillo",
                                component="grillo_chat_observer",
                            )
                        )
                        if text and interface_path:
                            if await _grillo_recent_same_message(
                                interface_path, text, window
                            ):
                                log_info(
                                    "[action_parser] Suppressing duplicate Grillo outbound message (within self-window)"
                                )
                                continue
                except Exception as e:
                    log_debug(f"[action_parser] Grillo dedupe check failed: {e}")

                # Block agent actions (propose_action, agent_execute, etc.)
                # from grillo beats — outreach should deliver directly to the
                # target interface, never route through the agent approval flow.
                if action_type in (
                    "propose_action",
                    "agent_execute",
                    "approve_action",
                    "start_task",
                ):
                    log_warning(
                        f"[action_parser] Dropping '{action_type}' from grillo beat — agent actions not allowed in grillo context"
                    )
                    continue

            if is_from_cortex:
                try:
                    # Centralized safety decision
                    from core.action_safety import is_action_allowed_for_execution

                    allowed, reason, meta = is_action_allowed_for_execution(
                        action, context or {}, original_message
                    )
                    if not allowed:
                        # Safety/policy blocks are unfixable — the LLM cannot
                        # change the system configuration, so asking the
                        # corrector to "fix" these only produces workarounds
                        # like propose_action that bypass the intended policy.
                        error_msg = f"Action '{action.get('type')}' blocked by safety policy: {reason}"
                        log_info(f"[action_parser] {error_msg}")
                        collected_errors.append(error_msg)
                        failed_actions.append(
                            {
                                "index": idx,
                                "action": action,
                                "errors": [error_msg],
                                "safety_meta": meta,
                                "unfixable": True,
                            }
                        )
                        continue

                    # Special-case: heuristic-recovered actions must not be auto-executed even if allowed
                    if action.get("metadata", {}).get("heuristic_recovery"):
                        error_msg = f"Action '{action.get('type')}' flagged as heuristic recovery and requires human validation; quarantined"
                        log_warning(f"[action_parser] {error_msg}")
                        collected_errors.append(error_msg)
                        failed_actions.append(
                            {"index": idx, "action": action, "errors": [error_msg]}
                        )
                        continue

                except Exception as e:
                    log_warning(f"[action_parser] Safety/autonomy checks failed: {e}")
                    # On error, be conservative and treat as proposal-only
                    error_msg = f"Action '{action.get('type')}' treated as proposal due to safety check failure"
                    collected_errors.append(error_msg)
                    failed_actions.append(
                        {"index": idx, "action": action, "errors": [error_msg]}
                    )
                    continue
            # --- End safety & autonomy checks ---

            log_debug(f"[action_parser] Running action {idx}: {action_type}")
            result = await run_action(action, context, bot, original_message)

            # Check if run_action returned error info
            if isinstance(result, dict) and "error" in result:
                collected_errors.append(result["error"])
                failed_actions.append(
                    {"index": idx, "action": action, "errors": [result["error"]]}
                )
            else:
                processed_actions.append(action)

                if action_type == "terminal" and isinstance(result, str):
                    terminal_seen = True
                    action_outputs.append(
                        {
                            "type": "terminal",
                            "command": action.get("payload", {}).get("command", ""),
                            "output": result,
                        }
                    )
                elif isinstance(result, dict) and result.get("deliver_to_llm"):
                    # Opt-in convention: a plugin's execute_action result tagged
                    # deliver_to_llm=True is fed back to the LLM so it can voice
                    # the fetched data in-character. This covers fetch-only
                    # actions whose answer *is* the reply (e.g. recall_last_dream):
                    # the action returns content but never sends, so without this
                    # the user would get nothing. The generic request_llm_delivery
                    # block below handles loop-prevention and message-scoped
                    # delivery. Unlike "terminal" this does NOT set terminal_seen,
                    # so sibling actions in the same batch keep executing normally.
                    delivery_output = {
                        k: v for k, v in result.items() if k != "deliver_to_llm"
                    }
                    delivery_output["type"] = action_type
                    action_outputs.append(delivery_output)

        except Exception as e:
            error_msg = f"Error executing action {idx}: {repr(e)}"
            log_error(f"[action_parser] {error_msg}")
            collected_errors.append(error_msg)
            failed_actions.append(
                {"index": idx, "action": action, "errors": [error_msg]}
            )

    # After all actions processed, mark scheduled event as delivered if applicable
    event_id = context.get("event_id") or getattr(original_message, "event_id", None)
    if event_id:
        try:
            from core import db

            if await db.mark_event_delivered(event_id):
                log_info(f"[action_parser] Event {event_id} marked delivered")
            else:
                log_warning(
                    f"[action_parser] Failed to mark event {event_id} delivered"
                )
        except Exception as e:
            log_warning(
                f"[action_parser] Error marking event {event_id} delivered: {e}"
            )
        try:
            from core import event_dispatcher

            event_dispatcher.event_completed(event_id)
        except Exception as e:
            log_warning(
                f"[action_parser] Failed to clear processing flag for event {event_id}: {e}"
            )

    if action_outputs:
        interface_name = context.get("interface")
        if not interface_name:
            log_error("No interface specified in action_parser context")
            return

        response_context = {
            "chat_id": getattr(original_message, "chat_id", None),
            "message_id": getattr(original_message, "message_id", None),
            "interface_name": interface_name,
            "interface_path": getattr(original_message, "interface_path", None),
        }

        try:
            from core.auto_response import request_llm_delivery

            # Prefer a real fetch-action type for the loop-prevention instruction
            # ("DO NOT call '<type>' again"); fall back to "terminal".
            delivery_action_type = next(
                (
                    o.get("type")
                    for o in action_outputs
                    if o.get("type") and o.get("type") != "terminal"
                ),
                "terminal",
            )

            await request_llm_delivery(
                action_outputs=action_outputs,
                original_context=response_context,
                action_type=delivery_action_type,
            )
        except Exception as e:
            log_warning(
                f"[action_parser] Failed to request LLM delivery for action outputs: {e}"
            )

    if collected_errors and failed_actions:
        # New selective corrector: only ask LLM to fix failed actions, not successful ones
        # Check both message object AND context for from_cortex flag
        is_from_cortex = (
            hasattr(original_message, "from_cortex") and original_message.from_cortex
        ) or context.get("from_cortex", False)

        if is_from_cortex:
            try:
                await _request_selective_correction(
                    failed_actions=failed_actions,
                    successful_actions=processed_actions,
                    bot=bot,
                    context=context,
                    original_message=original_message,
                )
            except Exception as e:
                log_warning(
                    f"[action_parser] Failed to invoke selective correction: {e}"
                )
        else:
            log_debug(
                "[action_parser] Errors found but message is not from LLM; skipping correction to prevent loops"
            )

    # Debrief hooks (postflight) before diary creation
    if not (context or {}).get("from_debrief"):
        try:
            from core.debrief import run_debrief

            if isinstance(context, dict):
                context["debrief_ran"] = True

            await run_debrief(
                processed_actions=processed_actions,
                failed_actions=failed_actions,
                results={
                    "processed": processed_actions,
                    "failed": failed_actions,
                    "errors": collected_errors,
                    "llm_response_text": (context or {}).get("llm_response_text"),
                },
                context=context,
                original_message=original_message,
            )
        except Exception as e:
            log_debug(f"[action_parser] Debrief failed: {e}")

    # Create diary entry for this interaction
    await _create_diary_entry_for_actions(processed_actions, context, original_message)

    return {
        "processed": processed_actions,
        "errors": collected_errors,
        "failed_actions": failed_actions,
        "action_outputs": action_outputs,
    }


def _llm_already_provided_diary_content(processed_actions: list) -> bool:
    """Return True if any action is create_personal_diary_entry with explicit content.

    When the LLM already provides a full diary entry with its own ``content``
    field, the automatic summary hook would duplicate it.  All Grillo beats
    (self_reflection, curiosity, memory_consolidation, …) send ``content`` in
    their diary payload, so this catches all of them.
    """
    for action in processed_actions:
        if action.get("type") != "create_personal_diary_entry":
            continue
        payload = action.get("payload") or {}
        content = (payload.get("content") or "").strip()
        if content:
            return True
    return False


async def _create_diary_entry_for_actions(processed_actions, context, original_message):
    """Create a diary entry summarizing the actions performed during this interaction."""
    if not processed_actions:
        return

    try:
        from plugins.ai_diary import create_personal_diary_entry, is_plugin_enabled

        if not is_plugin_enabled():
            log_debug("[action_parser] Diary plugin disabled, skipping diary entry")
            return

        if isinstance(context, dict) and (
            context.get("beat_type") == "diary_consolidation"
            or context.get("interface") == "diary_merge"
        ):
            log_debug(
                "[action_parser] Skipping automatic diary entry for internal diary consolidation"
            )
            return

        # If the LLM already provided a diary entry with explicit content,
        # skip the automatic summary — it would just append a duplicate fragment.
        if _llm_already_provided_diary_content(processed_actions):
            log_debug(
                "[action_parser] LLM provided explicit diary content — skipping automatic summary"
            )
            return

        # Extract relevant information
        interface_name = context.get("interface", "unknown")
        chat_id = getattr(original_message, "chat_id", None)
        thread_id = getattr(original_message, "thread_id", None)
        if thread_id is None:
            thread_id = getattr(original_message, "message_thread_id", None)
        if thread_id is None and isinstance(context, dict):
            thread_id = context.get("thread_id") or context.get("payload_thread_id")

        # Prefer LLM-provided diary metadata when present.
        # This avoids generic/hardcoded reflections unrelated to the real context.
        llm_diary_payload = _extract_diary_metadata_from_actions(
            processed_actions, context if isinstance(context, dict) else None
        )

        # Get user message from context or original_message
        user_message = ""
        if hasattr(original_message, "text"):
            user_message = original_message.text
        elif isinstance(original_message, dict) and "text" in original_message:
            user_message = original_message["text"]
        elif context and "input" in context and "payload" in context["input"]:
            payload = context["input"]["payload"]
            if "text" in payload:
                user_message = payload["text"]

        # Extract people involved from context participants for logging
        involved_people = set()
        if context and "participants" in context:
            for participant in context["participants"]:
                if "usertag" in participant:
                    # Remove @ from usertag
                    username = participant["usertag"].lstrip("@")
                    involved_people.add(username)
                # Also add nicknames if available
                if "nicknames" in participant and participant["nicknames"]:
                    for nickname in participant["nicknames"]:
                        if nickname and nickname.lower() not in ["synth", "bot"]:
                            involved_people.add(nickname)

        # Convert to list for logging purposes only (not passed to diary)
        involved_list = [
            person
            for person in involved_people
            if person.lower() not in ["synth", "bot"]
        ]

        # Generate comprehensive response content from all actions
        synth_response_parts = []
        action_types = [action.get("type", "unknown") for action in processed_actions]

        # Extract actual text from message actions
        for action in processed_actions:
            action_type = action.get("type", "")
            payload = action.get("payload", {})

            if action_type and _is_interface_message_action(action_type):
                text = payload.get("text", "")
                if text:
                    synth_response_parts.append(text)
            elif action_type == "terminal":
                command = payload.get("command", "")
                if command:
                    synth_response_parts.append(f"Executed command: {command}")
            elif action_type == "bio_update":
                target = payload.get("target", "someone")
                synth_response_parts.append(f"Updated bio information for {target}")
            elif action_type == "event":
                description = payload.get("description", "created an event")
                synth_response_parts.append(f"Scheduled event: {description}")

        # If no specific content found, create a summary
        if not synth_response_parts:
            action_counts = {}
            for action_type in action_types:
                action_counts[action_type] = action_counts.get(action_type, 0) + 1

            if len(action_counts) == 1:
                action_type = list(action_counts.keys())[0]
                count = action_counts[action_type]
                if count == 1:
                    synth_response_parts.append(f"Performed {action_type} action")
                else:
                    synth_response_parts.append(
                        f"Performed {count} {action_type} actions"
                    )
            else:
                action_summary = ", ".join(
                    [
                        f"{count} {action_type}"
                        for action_type, count in action_counts.items()
                    ]
                )
                synth_response_parts.append(
                    f"Performed multiple actions: {action_summary}"
                )

        synth_response = " | ".join(synth_response_parts)

        # Use payload tags if provided by LLM, otherwise keep automatic tag generation.
        payload_context_tags = llm_diary_payload.get("context_tags")
        if payload_context_tags:
            context_tags = payload_context_tags
        else:
            context_tags = _generate_context_tags(
                action_types, synth_response, user_message, interface_name
            )

        # Use create_personal_diary_entry with heuristics disabled.
        # We only persist diary metadata explicitly provided by the LLM payload.
        create_personal_diary_entry(
            synth_response=synth_response,
            user_message=user_message if user_message else None,
            context_tags=context_tags,
            involved_users=involved_list,
            interface=interface_name,
            chat_id=str(chat_id) if chat_id else None,
            thread_id=str(thread_id) if thread_id is not None else None,
            grillo_activity_log_id=_extract_grillo_activity_log_id(
                context if isinstance(context, dict) else None,
                original_message,
            ),
            interaction_summary=llm_diary_payload.get("interaction_summary"),
            personal_thought=llm_diary_payload.get("personal_thought"),
            emotions=llm_diary_payload.get("emotions"),
        )

        log_debug(f"[action_parser] Created personal diary entry: {synth_response}")

    except Exception as e:
        log_warning(f"[action_parser] Failed to create diary entry: {e}")
        import traceback

        log_debug(f"[action_parser] Diary error traceback: {traceback.format_exc()}")


def _generate_context_tags(
    action_types: List[str], synth_response: str, user_message: str, interface_name: str
) -> List[str]:
    """Generate specific context tags based on action types and conversation content."""
    context_tags = []

    # Action-based tags (more specific than before)
    if "bio_update" in action_types or "bio_full_request" in action_types:
        context_tags.append("personal_info")
    if "terminal" in action_types:
        context_tags.append("technical")
    if "event" in action_types:
        context_tags.append("scheduling")
    if (
        "speech_selenium_elevenlabs" in action_types
        or "audio_telegram_bot" in action_types
    ):
        context_tags.append("audio")

    # Content-based analysis for specific topics
    combined_text = (synth_response + " " + (user_message or "")).lower()

    # Food and dining
    if any(
        word in combined_text
        for word in ["food", "eat", "cooking", "recipe", "restaurant", "meal"]
    ):
        context_tags.append("food")
        # Specific food types
        if any(word in combined_text for word in ["sushi", "japanese"]):
            context_tags.append("sushi")
        if any(word in combined_text for word in ["pizza", "italian"]):
            context_tags.append("pizza")
        if any(word in combined_text for word in ["restaurant", "dining"]):
            context_tags.append("restaurant")

    # Cars and vehicles
    if any(
        word in combined_text
        for word in [
            "car",
            "auto",
            "vehicle",
            "driving",
            "motor",
            "bmw",
            "audi",
            "honda",
        ]
    ):
        context_tags.append("cars")
        if any(
            word in combined_text for word in ["color", "blue", "red", "black", "white"]
        ):
            context_tags.append("colors")

    # Technology and computers
    if any(
        word in combined_text
        for word in ["computer", "software", "programming", "code", "tech"]
    ):
        context_tags.append("technology")

    # Entertainment
    if any(
        word in combined_text
        for word in ["movie", "music", "game", "book", "entertainment"]
    ):
        context_tags.append("entertainment")

    # Location and travel
    if any(
        word in combined_text
        for word in ["travel", "vacation", "city", "country", "location"]
    ):
        context_tags.append("travel")

    # Work and career
    if any(
        word in combined_text
        for word in ["work", "job", "career", "office", "business"]
    ):
        context_tags.append("work")

    # Health and wellness
    if any(
        word in combined_text for word in ["health", "exercise", "fitness", "medical"]
    ):
        context_tags.append("health")

    # Family and relationships
    if any(
        word in combined_text
        for word in ["family", "friend", "relationship", "love", "marriage"]
    ):
        context_tags.append("relationships")

    # Only add help tag for explicit help requests
    if any(
        word in combined_text
        for word in ["help me", "can you help", "need help", "assistance"]
    ):
        context_tags.append("help")

    # Only add learning tag for explicit learning conversations
    if any(
        word in combined_text
        for word in ["learn", "teach", "explain", "understand", "study"]
    ):
        context_tags.append("learning")

    # Only add problem tag for explicit problem-solving
    if any(
        word in combined_text
        for word in ["problem", "issue", "error", "fix", "solve", "bug"]
    ):
        context_tags.append("problem")

    # Remove duplicate tags and return
    return list(set(context_tags))


async def parse_action(action: dict, bot, message):
    """Parse and execute a single action."""
    log_debug(
        "[action_parser] Received action: "
        + json_dumps(redact_multimodal_for_logging(action))
    )

    action_type = action.get("type")
    interface = action.get("interface")
    payload = action.get("payload")

    if not action_type or not payload:
        log_warning("[action_parser] Invalid action structure: missing type or payload")
        return

    log_debug(
        "[action_parser] Action type: "
        + str(action_type)
        + ", Interface: "
        + str(interface)
        + ", Payload: "
        + json_dumps(redact_multimodal_for_logging(payload))
    )

    # First allow the active LLM plugin to handle custom actions
    import core.plugin_instance as plugin_instance

    llm_plugin = getattr(plugin_instance, "plugin", None)
    if llm_plugin:
        try:
            supported = []
            if hasattr(llm_plugin, "get_supported_action_types"):
                supported = llm_plugin.get_supported_action_types()
            elif hasattr(llm_plugin, "get_supported_actions"):
                acts = llm_plugin.get_supported_actions()
                if isinstance(acts, dict):
                    supported = list(acts.keys())
            if action_type in supported and hasattr(llm_plugin, "handle_custom_action"):
                await llm_plugin.handle_custom_action(action_type, payload)
                return
        except Exception:
            pass

    # Use centralized action plugin system for all other action types
    action_plugins = _plugins_for(action_type)
    if action_plugins:
        action_handled = False
        for plugin in action_plugins:
            try:
                if hasattr(plugin, "execute_action"):
                    result = plugin.execute_action(action, {}, bot, message)
                    if inspect.iscoroutine(result):
                        await result
                    action_handled = True
                    log_debug(
                        f"[action_parser] Action {action_type} handled by {plugin.__class__.__name__}"
                    )
                    break  # Stop after first successful handler
                elif hasattr(plugin, "handle_custom_action"):
                    await plugin.handle_custom_action(action_type, payload)
                    action_handled = True
                    log_debug(
                        f"[action_parser] Action {action_type} handled by {plugin.__class__.__name__} (custom)"
                    )
                    break  # Stop after first successful handler
                else:
                    log_warning(
                        f"[action_parser] Plugin {plugin.__class__.__name__} lacks execute_action/handle_custom_action methods"
                    )
            except Exception as e:
                log_error(
                    f"[action_parser] Error delegating {action_type} to plugin {plugin.__class__.__name__}: {repr(e)}"
                )

        if action_handled:
            log_debug(f"[action_parser] Action {action_type} successfully handled")
        else:
            log_warning(
                f"[action_parser] No plugin successfully handled action {action_type}"
            )
        return

    log_warning(
        f"[action_parser] No plugin supports action type '{action_type}' — no plugin handler found"
    )


async def initialize_core(notify_fn=None):
    """Initialize and log all core components."""
    from core.core_initializer import core_initializer

    return await core_initializer.initialize_all(notify_fn=notify_fn)


def get_action_plugin_instructions() -> dict[str, Any]:
    """Gather prompt instructions from all action plugins."""
    instructions: dict[str, Any] = {}
    try:
        for plugin in _load_action_plugins():
            if hasattr(plugin, "get_supported_actions") and hasattr(
                plugin, "get_prompt_instructions"
            ):
                supported = plugin.get_supported_actions()
                for action in supported:
                    try:
                        instr = plugin.get_prompt_instructions(action)
                        if instr:
                            instructions[action] = instr
                    except Exception:
                        log_warning(
                            f"[action_parser] Plugin {plugin.__class__.__name__} missing prompt instructions for '{action}'"
                        )
    except Exception as e:
        log_error(
            f"[action_parser] Error collecting plugin prompt instructions: {repr(e)}"
        )

    return instructions


async def gather_static_injections(message=None, context_memory=None):
    """Gathers static contextual data from all plugins that support 'static_inject'.

    This is used to build the context for every prompt with information like
    date, time, weather, persona, etc.
    """
    injections = {}
    loaded_plugins = _load_action_plugins()
    log_info(
        f"[action_parser] gather_static_injections: Querying {len(loaded_plugins)} plugins"
    )

    tasks = []
    plugin_names = []

    for plugin in loaded_plugins:
        try:
            supported = False
            if hasattr(plugin, "get_supported_action_types"):
                supported = "static_inject" in (
                    plugin.get_supported_action_types() or []
                )
            if not supported and hasattr(plugin, "get_supported_actions"):
                actions = plugin.get_supported_actions()
                supported = isinstance(actions, dict) and "static_inject" in actions

            has_method = hasattr(plugin, "get_static_injection")

            if not supported or not has_method:
                continue

            # Wrapper to handle both sync/async and different signatures
            async def _run_injection(p=plugin):
                name = p.__class__.__name__
                start = time.time()
                cache_key = f"{p.__class__.__module__}.{p.__class__.__qualname__}"
                allow_stale_fallback = bool(
                    getattr(p, "allow_static_injection_stale_fallback", False)
                )
                cache_ttl_seconds = float(
                    getattr(p, "static_injection_cache_ttl_seconds", 0.0) or 0.0
                )

                def _stale_fallback(reason: str) -> dict[str, Any]:
                    if not allow_stale_fallback:
                        return {}

                    cached_entry = _STATIC_INJECTION_CACHE.get(cache_key)
                    if not cached_entry:
                        return {}

                    cached_at, cached_payload = cached_entry
                    age_seconds = time.time() - cached_at
                    if cache_ttl_seconds > 0 and age_seconds > cache_ttl_seconds:
                        _STATIC_INJECTION_CACHE.pop(cache_key, None)
                        log_warning(
                            f"[action_parser] Stale static injection cache for {name} expired after {age_seconds:.1f}s"
                        )
                        return {}

                    log_warning(
                        f"[action_parser] Using cached static injection for {name} after {reason} ({age_seconds:.1f}s old)"
                    )
                    return dict(cached_payload)

                try:
                    # Enforce a strict timeout per-plugin to prevent hangs
                    async def _inner():
                        # Try with arguments first
                        try:
                            res = p.get_static_injection(message, context_memory)
                        except TypeError:
                            # Fallback to no arguments
                            res = p.get_static_injection()

                        if inspect.iscoroutine(res):
                            res = await res
                        return res

                    try:
                        res = await asyncio.wait_for(_inner(), timeout=5.0)
                    except asyncio.TimeoutError:
                        log_error(
                            f"[action_parser] ⏰ get_static_injection() on {name} timed out after 5s"
                        )
                        return _stale_fallback("timeout")

                    duration = time.time() - start
                    if duration > 0.1:
                        log_info(
                            f"[action_parser] ⚠️ get_static_injection() on {name} took {duration:.3f}s"
                        )
                    else:
                        log_debug(
                            f"[action_parser] ✅ get_static_injection() on {name} took {duration:.3f}s"
                        )

                    if isinstance(res, dict):
                        if allow_stale_fallback:
                            _STATIC_INJECTION_CACHE[cache_key] = (
                                time.time(),
                                dict(res),
                            )
                        return res
                    return {}
                except Exception as e:
                    log_error(
                        f"[action_parser] Error in get_static_injection() on {name}: {e}"
                    )
                    return _stale_fallback("error")

            tasks.append(_run_injection())
            plugin_names.append(plugin.__class__.__name__)

        except Exception as e:
            log_error(f"[action_parser] Error preparing injection for {plugin}: {e}")

    if not tasks:
        # Return empty dict if no injections
        return {}

    log_debug(
        f"[action_parser] Running {len(tasks)} injections in parallel: {plugin_names}"
    )
    try:
        results = await asyncio.gather(*tasks, return_exceptions=True)
        for res in results:
            if isinstance(res, dict):
                injections.update(res)
            elif isinstance(res, Exception):
                log_error(
                    f"[action_parser] asyncio.gather task raised exception: {res}"
                )
    except Exception as e:
        log_error(f"[action_parser] Error in asyncio.gather results: {e}")

    log_info(
        f"[action_parser] 📊 gather_static_injections() returning {len(injections)} keys: {list(injections.keys())}"
    )
    return injections


def _is_restricted_action(action_type: str) -> bool:
    """Return True if the action is marked as restricted."""
    try:
        for plugin in _load_action_plugins():
            if hasattr(plugin, "get_supported_actions"):
                actions = plugin.get_supported_actions()
                if isinstance(actions, dict):
                    meta = actions.get(action_type)
                    if isinstance(meta, dict) and meta.get("restricted"):
                        return True
    except Exception:
        pass
    try:  # Check interface actions as well
        from core.core_initializer import INTERFACE_REGISTRY

        for iface in INTERFACE_REGISTRY.values():
            if hasattr(iface, "get_supported_actions"):
                actions = iface.get_supported_actions()
                if isinstance(actions, dict):
                    meta = actions.get(action_type)
                    if isinstance(meta, dict) and meta.get("restricted"):
                        return True
    except Exception:
        pass
    return False


__all__ = [
    "run_action",
    "run_actions",
    "parse_action",
    "validate_action",
    "initialize_core",
    "get_action_plugin_instructions",
    "gather_static_injections",
    "corrector_orchestrator",
]


async def corrector_orchestrator(
    text: str,
    context: dict,
    bot,
    message,
    max_retries: int | None = None,
    completed_actions: list | None = None,
    force_correction: bool = False,
):
    """Process model text: parse JSON actions or run the corrector loop.

    Args:
        text: The text to parse/correct
        context: Context information
        bot: Bot instance
        message: Message object
        max_retries: Maximum number of correction attempts
        completed_actions: List of action types that were already successfully executed
                          (so the corrector knows not to regenerate them)
        force_correction: If True, force the corrector to run even for non-JSON-like text
                         (used when LLM returns plain text that violates JSON-only instructions)

    Returns:
        True  -> actions parsed and executed
        False -> blocked (corrector exhausted or not allowed)
        None  -> not JSON-like; caller may forward as plain text
    """
    # Only handle messages that explicitly originate from the AI/cortex layer.
    # We signal this with a single flag `from_cortex` on the message or in the
    # context; legacy `from_cortex`/`from_ai` names are no longer used.
    origin_flag = False
    try:
        origin_flag = bool(
            getattr(message, "from_cortex", False)
            or (context or {}).get("from_cortex", False)
        )
    except Exception:
        origin_flag = False

    if message is not None and not origin_flag:
        log_debug(
            "[corrector_orchestrator] Ignoring message: not marked as cortex-origin"
        )
        return None

    # Determine max retries
    if max_retries is None:
        max_retries = int(CORRECTOR_RETRIES)

    # Initialize completed_actions if not provided
    if completed_actions is None:
        completed_actions = []

    # Quick parse attempt
    parsed = None
    try:
        parsed = _extract_json_local(text)
    except Exception as e:
        log_debug(f"[corrector_orchestrator] initial parse failed: {e}")

    if parsed is not None:
        # Build actions list similar to transport layer
        if isinstance(parsed, dict) and "actions" in parsed:
            actions = parsed["actions"] if isinstance(parsed["actions"], list) else None
            if actions is None:
                log_warning("[corrector_orchestrator] actions field must be a list")
                return None
        elif isinstance(parsed, list):
            actions = parsed
        elif isinstance(parsed, dict) and "type" in parsed:
            actions = [parsed]
        else:
            log_warning(
                f"[corrector_orchestrator] Unrecognized JSON structure: {parsed}"
            )
            return None

        # Filter out already completed actions to avoid duplicates (e.g., double diary entries)
        if completed_actions:
            original_count = len(actions)
            actions = [a for a in actions if a.get("type") not in completed_actions]
            if len(actions) < original_count:
                log_info(
                    f"[corrector_orchestrator] Filtered out {original_count - len(actions)} already-completed actions: {completed_actions}"
                )

        # If no actions left after filtering, we're done
        if not actions:
            log_info(
                "[corrector_orchestrator] All actions were already completed - nothing to regenerate"
            )
            return True

        # If the parsed LLM JSON contains extra top-level keys (other than
        # 'actions'), treat each unregistered key as an invalid action. This
        # keeps validation strictly aligned to the registry of actions and
        # avoids hard-coded key checks. Components may register allowed
        # response metadata keys via the validation registry.
        try:
            if isinstance(parsed, dict):
                from core.validation_registry import get_validation_registry

                allowed_metadata = (
                    get_validation_registry().get_response_metadata_keys()
                )
                extra_keys = [
                    k
                    for k in parsed.keys()
                    if k != "actions"
                    and k not in allowed_metadata
                    and not k.startswith("meta.")
                ]

                if extra_keys:
                    # Mapping from interface prefix to the correct message
                    # action type — mirrors _INTERFACE_TO_MESSAGE_ACTION in
                    # message_chain but kept inline to avoid circular imports.
                    _iface_msg_map: dict[str, str] = {
                        "telegram_bot": "message_telegram_bot",
                        "discord_bot": "message_discord_bot",
                        "synth_webui": "message_synth_webui",
                        "matrix_chat": "message_matrix_chat",
                        "ollama_serve": "message_ollama_serve",
                    }
                    _message_like_keys = {"message", "text", "reply", "response"}
                    ctx_ipath = (context or {}).get("interface_path")

                    synthetic_actions: list[dict] = []
                    for key in extra_keys:
                        value = parsed.get(key)
                        # Message-like keys with string values → map to a
                        # proper interface message action so the reply
                        # reaches the user instead of failing validation.
                        if key in _message_like_keys and isinstance(value, str):
                            # Skip if the same text is already in an
                            # explicit message action (avoid duplicates).
                            already_present = any(
                                isinstance(a, dict)
                                and isinstance(a.get("type"), str)
                                and a["type"].startswith("message_")
                                and isinstance(a.get("payload"), dict)
                                and a["payload"].get("text") == value
                                for a in actions
                            )
                            if already_present:
                                log_debug(
                                    f"[corrector_orchestrator] Skipping synthetic '{key}' — text already in explicit message action"
                                )
                                continue

                            payload: dict = {"text": value}
                            synthetic_type = key
                            if ctx_ipath:
                                iface_prefix = str(ctx_ipath).split("/")[0]
                                resolved = _iface_msg_map.get(iface_prefix)
                                if resolved:
                                    synthetic_type = resolved
                                payload["interface_path"] = str(ctx_ipath)
                        elif isinstance(value, dict):
                            payload = value
                            synthetic_type = key
                        else:
                            payload = {"value": value}
                            synthetic_type = key

                        synthetic_actions.append(
                            {"type": synthetic_type, "payload": payload}
                        )

                    actions.extend(synthetic_actions)
                    if synthetic_actions:
                        log_info(
                            f"[corrector_orchestrator] Added {len(synthetic_actions)} synthetic actions for unregistered top-level keys: {', '.join(extra_keys)}"
                        )
        except Exception as _e:
            log_debug(
                f"[corrector_orchestrator] Error while processing top-level keys: {_e}"
            )

        try:
            result = await run_actions(actions, context, bot, message)
            # If at least one action was processed successfully, consider it a success
            # even when other actions produced errors (partial success).  We must check
            # `processed` BEFORE `errors` to preserve this invariant.
            if isinstance(result, dict) and result.get("processed"):
                log_info(
                    "[corrector_orchestrator] Actions executed successfully - interrupting correction loop"
                )
                return True
            # No actions processed.  If there are errors, attempt trivial auto-fix
            # (e.g. numeric-string → int coercion) before giving up entirely.
            if isinstance(result, dict) and result.get("errors"):
                if _attempt_auto_fix(actions):
                    log_info(
                        "[corrector_orchestrator] Attempting automatic fix for minor errors"
                    )
                    result2 = await run_actions(actions, context, bot, message)
                    if isinstance(result2, dict) and result2.get("processed"):
                        log_info(
                            "[corrector_orchestrator] Automatic fix succeeded; continuing without LLM correction"
                        )
                        return True
                log_warning(
                    f"[corrector_orchestrator] Actions failed with errors: {result.get('errors')}"
                )
                return False
            # No processed and no explicit errors – treat as success (empty but valid)
            log_info(
                "[corrector_orchestrator] Actions executed successfully - interrupting correction loop"
            )
            return True
        except Exception as e:
            log_warning(f"[corrector_orchestrator] Failed to run actions: {e}")
            return False

    # Not parsed initially. If not JSON-like, check if we should force correction
    if "{" not in (text or "") and "[" not in (text or ""):
        if not force_correction:
            # Not JSON-like and not forced -> indicate to caller to forward as plain text
            return None
        else:
            # force_correction=True: LLM returned plain text violating JSON-only rule
            # Fall through to run corrector loop
            log_info(
                "[corrector_orchestrator] Plain text detected with force_correction=True - running corrector loop to request JSON format"
            )

    # JSON-like but not valid (or forced correction for plain text) -> run corrector loop here
    # Build context for corrector, including completed actions
    if completed_actions:
        log_info(
            f"[corrector_orchestrator] Starting correction loop - actions already completed: {completed_actions}"
        )
        context = dict(context) if context else {}
        context["completed_actions"] = completed_actions
        context["instruction"] = (
            f"The previous response had corrupted JSON. These actions were already successfully executed: {', '.join(completed_actions)}. Please regenerate ONLY the missing/corrupted actions. Do NOT regenerate: {', '.join(completed_actions)}"
        )

    tried_texts = set()
    attempt = 0
    while attempt < max_retries:
        # Check retry permission
        if not _should_retry(message, max_retries=max_retries):
            retry_key = _get_retry_key(message)
            retry_count, _ = _retry_tracker.get(retry_key, (0, 0))
            log_warning(
                f"[corrector_orchestrator] Max retries ({retry_count}) reached for {retry_key}; blocking"
            )
            return False

        # increment retry counter
        _increment_retry(message)
        attempt += 1

        # Call the corrector (transport-layer middleware)
        try:
            import core.transport_layer as transport

            # Add message to context for error handling
            context = dict(context) if context else {}
            context["message"] = message
            # Pass thread_id from original message to maintain conversation continuity
            corrected = await transport.run_corrector_middleware(
                text,
                bot=bot,
                context=context,
                chat_id=getattr(message, "chat_id", None),
                thread_id=getattr(message, "thread_id", None),
            )
        except Exception as e:
            log_warning(f"[corrector_orchestrator] Corrector invocation failed: {e}")
            return False

        if corrected is None:
            log_debug(
                f"[corrector_orchestrator] Corrector returned None on attempt {attempt}"
            )
            # corrected failed; loop will check retry and possibly continue
            text = text  # keep original or last value
            continue

        # If corrected same as previous tried value, avoid infinite loop
        if corrected in tried_texts:
            log_warning(
                "[corrector_orchestrator] Corrector returned previously seen output; attempting to execute already-parsed actions if available"
            )
            # Try to execute already-parsed actions from the original text instead of blocking completely
            if parsed is not None:
                log_info(
                    "[corrector_orchestrator] Attempting to execute actions from originally-parsed JSON before blocking"
                )
                # Build actions list
                if isinstance(parsed, dict) and "actions" in parsed:
                    actions = (
                        parsed["actions"]
                        if isinstance(parsed["actions"], list)
                        else None
                    )
                elif isinstance(parsed, list):
                    actions = parsed
                elif isinstance(parsed, dict) and "type" in parsed:
                    actions = [parsed]
                else:
                    actions = None

                if actions:
                    # Filter out already-completed actions
                    if completed_actions:
                        original_count = len(actions)
                        actions = [
                            a for a in actions if a.get("type") not in completed_actions
                        ]
                        log_info(
                            f"[corrector_orchestrator] Filtered {original_count - len(actions)} already-completed actions"
                        )

                    if actions:
                        try:
                            result = await run_actions(actions, context, bot, message)
                            if isinstance(result, dict) and result.get("processed"):
                                log_info(
                                    "[corrector_orchestrator] Successfully executed originally-parsed actions despite loop"
                                )
                                return True
                        except Exception as e:
                            log_warning(
                                f"[corrector_orchestrator] Failed to execute originally-parsed actions: {e}"
                            )

            log_warning(
                "[corrector_orchestrator] No valid actions to execute; blocking due to loop"
            )
            return False
        tried_texts.add(corrected)

        # Try parsing corrected
        try:
            parsed2 = _extract_json_local(corrected)
        except Exception as e:
            parsed2 = None
            log_debug(f"[corrector_orchestrator] Parsing corrected failed: {e}")

        if parsed2 is not None:
            # run actions
            if isinstance(parsed2, dict) and "actions" in parsed2:
                actions = (
                    parsed2["actions"] if isinstance(parsed2["actions"], list) else None
                )
                if actions is None:
                    log_warning(
                        "[corrector_orchestrator] corrected actions field must be a list"
                    )
                    return False
            elif isinstance(parsed2, list):
                actions = parsed2
            elif isinstance(parsed2, dict) and "type" in parsed2:
                actions = [parsed2]
            else:
                log_warning(
                    f"[corrector_orchestrator] Unrecognized corrected JSON structure: {parsed2}"
                )
                return False

            try:
                result = await run_actions(actions, context, bot, message)
                # Check if any actions were processed successfully
                if isinstance(result, dict) and result.get("processed"):
                    log_info(
                        "[corrector_orchestrator] Corrected actions executed successfully - interrupting correction loop"
                    )
                    return True
                elif isinstance(result, dict) and result.get("errors"):
                    log_warning(
                        f"[corrector_orchestrator] Corrected actions failed with errors: {result.get('errors')}"
                    )
                    return False
                else:
                    log_info(
                        "[corrector_orchestrator] Corrected actions executed successfully - interrupting correction loop"
                    )
                    return True
            except Exception as e:
                log_warning(
                    f"[corrector_orchestrator] Failed to run actions after correction: {e}"
                )
                return False

        # Not parsed; set text to corrected and retry
        text = corrected

    # Exhausted retries
    log_warning(
        f"[corrector_orchestrator] Exhausted {max_retries} correction attempts; blocking message for chat {getattr(message, 'chat_id', None)}"
    )
    return False
